SELECT percentile_cont(0.25) within GROUP (ORDER BY l.value) AS instability_score, COUNT(DISTINCT CASE WHEN l.value < -1 THEN l.subject_id END) AS critical_events, COUNT(DISTINCT CASE WHEN l.value < -1 THEN l.subject_id END) / NULLIF((SELECT COUNT(DISTINCT subject_id) FROM w70), 0) AS critical_ratio, (SELECT AVG(los) FROM icustays WHERE subject_id IN (SELECT subject_id FROM w65_75)) AS avg_los, (SELECT AVG(dod) FROM patients WHERE subject_id IN (SELECT subject_id FROM w65_75)) AS avg_mortality FROM labevents l WHERE l.subject_id IN (SELECT subject_id FROM w65_75);